// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Contract tests for boundedDelay valid, boundary, and rejected inputs.
// @spec: COR
// @consumers: fixture consumer
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { boundedDelay } from './delay.ts';

test('[COR-REQ-1] public behavior', () => {
  // contract: return the smaller finite nonnegative millisecond bound, including zero
  // non-goal: never start a timer or mutate either input while doing so
  // #region START_PUBLIC_SETUP_CASES
  const acceptedCases: ReadonlyArray<readonly [value: number, limit: number, expected: number]> = [
    [200, 50, 50],
    [50, 200, 50],
    [50, 50, 50],
    [0, 50, 0],
    [0, 0, 0],
  ];
  // #endregion END_PUBLIC_SETUP_CASES

  // #region START_PUBLIC_ASSERT_RESULT
  for (const [value, limit, expected] of acceptedCases) {
    assert.strictEqual(boundedDelay(value, limit), expected);
  }
  // #endregion END_PUBLIC_ASSERT_RESULT
});

test('[COR-REQ-2] invalid input', () => {
  // failure mode: every non-number, non-finite, or negative bound is rejected with RangeError
  // #region START_INVALID_SETUP_CASES
  const invalidCases: ReadonlyArray<readonly [value: number, limit: number]> = [
    ['200' as unknown as number, 50],
    [200, '50' as unknown as number],
    [Infinity, 50],
    [200, Infinity],
    [NaN, 50],
    [200, NaN],
    [-1, 50],
    [200, -1],
  ];
  // #endregion END_INVALID_SETUP_CASES

  // #region START_INVALID_ASSERT_REJECTION
  for (const [value, limit] of invalidCases) {
    assert.throws(() => boundedDelay(value, limit), RangeError);
  }
  // #endregion END_INVALID_ASSERT_REJECTION
});

// @file: Pure bounded delay rule for the COR core module.
// @spec: COR
// @consumers: fixture consumer

/**
 * @purpose Reject a value that is not a finite nonnegative number of milliseconds.
 * @invariant Runtime validation only; TypeScript annotations do not enforce this check.
 * @param value Candidate millisecond value.
 * @param argumentName Name of the rejected argument for the failure message.
 * @throws {RangeError} When the value is not a number, not finite, or negative.
 */
function verifyMilliseconds(value: number, argumentName: string): void {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new RangeError(`[boundedDelay] ${argumentName} must be a finite nonnegative number, received ${String(value)}`);
  }
}

/**
 * @purpose Return the smaller of two approved millisecond bounds without waiting.
 * @param value Requested delay in milliseconds.
 * @param limit Maximum allowed delay in milliseconds.
 * @throws {RangeError} When either argument is not a number, not finite, or negative.
 * @returns The smaller input, including zero, with no timer started.
 */
export function boundedDelay(value: number, limit: number): number {
  verifyMilliseconds(value, 'value');
  verifyMilliseconds(limit, 'limit');
  return Math.min(value, limit);
}
